const CACHE='serene-v1',FILES=['./','./index.html','./style.css','./app.js','./pdf.mjs','./pdf.worker.mjs','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png'];self.addEventListener('install',()=>self.skipWaiting());self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));self.addEventListener('message',e=>{if(e.data==='CACHE_APP')e.waitUntil((async()=>{try{const c=await caches.open(CACHE);await c.addAll(FILES);e.ports[0].postMessage({ok:true})}catch(err){await caches.delete(CACHE);e.ports[0].postMessage({ok:false,error:'Could not save all app files. Check your connection and retry.'})}})())});self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==location.origin)return;e.respondWith((async()=>{const cached=await caches.match(e.request);try{const response=await fetch(e.request);return response}catch{if(cached)return cached;if(e.request.mode==='navigate')return await caches.match('./index.html');throw Error('Offline and file not cached')}})())});
